/// <summary>
/// PaffH 05.11.25
/// </summary>
/// <returns>NDXHelperHTMLBVEMailRequestControlCenterAIDB</returns>
public static NDXHelperHTMLBVEMailRequestControlCenterAIDB construct()
{
    NDXHelperHTMLBVEMailRequestControlCenterAIDB  helperHTML = new NDXHelperHTMLBVEMailRequestControlCenterAIDB();
    helperHTML.backGroundColor = 'rgb(255, 250, 181)';
    helperHTML.blockLevel = 'p';
    helperHTML.border = '1px solid DodgerBlue';
    helperHTML.textAllign = 'left';
    helperHTML.fontFamily = 'courier';
    helperHTML.fontSize = '140%';

    return helperHTML;
}

/// <summary>
/// PaffH 05.11.25
/// </summary>
/// <returns>str</returns>
public static str emptyHtml()
{
    NDXHelperHTMLBVEMailRequestControlCenterAIDB  helperHTML = NDXHelperHTMLBVEMailRequestControlCenterAIDB::construct();
    helperHTML.initialize();
    helperHTML.blockLevel = 'h1';
    helperHTML.textAllign = 'center';
    helperHTML.textColor = 'rgb(255, 255, 255)';
    helperHTML.backGroundColor = 'rgb(206, 206, 206)';
    helperHTML.border = '2px solid DodgerBlue';
    helperHTML.doEscapeHtmlTags = false;

    //return helperHTML.buildHtml('<br><<< ohne Inhalt >>><br><br>');
    return helperHTML.buildHtml('<<< ohne Inhalt >>>');
}
